argv:
$ErrorActionPreference='Continue'
$o=[ordered]@{check='read_only_nonproxy_connectivity'}
$hosts=@('www.avito.ru','avito.ru','www.cian.ru','ya.ru')
$o.dns=@($hosts|ForEach-Object{$h=$_;$ips=@(Resolve-DnsName -Name $h -Type A -DnsOnly -ErrorAction SilentlyContinue|Where-Object {$_.Type -eq 'A'}|Select-Object -ExpandProperty IPAddress);@{host=$h;resolved=($ips.Count -gt 0);addressCount=$ips.Count;loopbackOrBlocked=(@($ips|Where-Object{$_ -match '^(0\.|127\.|10\.|192\.168\.|172\.(1[6-9]|2[0-9]|3[0-1])\.)'}).Count -gt 0)}})
$o.connect=@()
foreach($url in @('https://www.avito.ru/','https://avito.ru/','https://krasnoyarsk.cian.ru/','https://ya.ru/')){
 $out=(& curl.exe --noproxy '*' --connect-timeout 4 --max-time 7 --location --silent --show-error --output NUL --write-out '%{http_code}' $url 2>$null)
 $o.connect+=@{site=([uri]$url).Host;status=if("$out" -match '^\d{3}$'){"$out"}else{'failed'};exitCode=$LASTEXITCODE}
}
$o|ConvertTo-Json -Depth 5 -Compress
